        crossReferenceParts: [ { partName: "High Pressure Fuel Pump", category: "Fuel", oem: { brand: "Audi Genuine", code: "059130755BS", approxPrice: "950 EUR" }, crossRef: { brand: "Bosch", code: "0445010620", approxPrice: "650 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059130755bs", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059130755bs" }, note: "CRITICAL: CP4.2 pump. Fragile." }, { partName: "Upper Chain Tensioner", category: "Engine", oem: { brand: "Audi Genuine", code: "059109467E", approxPrice: "180 EUR" }, crossRef: { brand: "INA", code: "551011610", approxPrice: "90 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059109467e", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059109467e" }, note: "Right bank tensioner." }, { partName: "Glow Plug", category: "Ignition", oem: { brand: "Audi Genuine", code: "059905061H", approxPrice: "35 EUR" }, crossRef: { brand: "Beru", code: "GE115", approxPrice: "18 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059905061h", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059905061h" }, note: "Requires 6 units." }, { partName: "Water Pump", category: "Cooling", oem: { brand: "Audi Genuine", code: "059121012B", approxPrice: "150 EUR" }, crossRef: { brand: "Hepu", code: "P657", approxPrice: "80 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059121012b", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059121012b" }, note: "Metal impeller." }, { partName: "Thermostat", category: "Cooling", oem: { brand: "Audi Genuine", code: "059121111N", approxPrice: "75 EUR" }, crossRef: { brand: "Wahler", code: "410204.87D", approxPrice: "35 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059121111n", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059121111n" }, note: "87 degree." }, { partName: "Serpentine Belt", category: "Maintenance", oem: { brand: "Audi Genuine", code: "059903137H", approxPrice: "60 EUR" }, crossRef: { brand: "Continental", code: "6PK2404", approxPrice: "25 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059903137h", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059903137h" }, note: "Main drive belt." }, { partName: "Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "059198405", approxPrice: "22 EUR" }, crossRef: { brand: "Mann-Filter", code: "HU814/2x", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/059198405", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=059198405" }, note: "VW 507 00 only." }, { partName: "Fuel Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "7L6127434C", approxPrice: "65 EUR" }, crossRef: { brand: "Mann-Filter", code: "WK8034", approxPrice: "35 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/7l6127434c", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=7l6127434c" }, note: "Critical for CP4.2." }, { partName: "AdBlue Heater Unit", category: "Exhaust", oem: { brand: "Audi Genuine", code: "4L0198970C", approxPrice: "450 EUR" }, crossRef: { brand: "Bosch", code: "F01C600264", approxPrice: "250 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/4l0198970c", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=4l0198970c" }, note: "Fixes SCR heater failures." }, { partName: "NOx Sensor", category: "Exhaust", oem: { brand: "Audi Genuine", code: "4L0907807AB", approxPrice: "380 EUR" }, crossRef: { brand: "Bosch", code: "0281006114", approxPrice: "220 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/4l0907807ab", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=4l0907807ab" }, note: "Critical for SCR emissions." } ],
