  torqueSpecs: [ { part: "Engine Oil Drain Plug", value: "30 Nm", note: "Replace the plastic quarter-turn plug." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque into a cold cylinder head." }, { part: "Wheel Bolts", value: "160 Nm", note: "Apply in a precise star pattern." }, { part: "Ignition Coil Bolts", value: "10 Nm", note: "Do not overtighten into plastic covers." }, { part: "Valve Cover Bolts", value: "9 Nm", note: "Crisscross sequence from the center." }, { part: "Thermal Management Module", value: "9 Nm", note: "Tighten evenly to prevent leaks." }, { part: "Hot-V Turbo Heat Shield", value: "10 Nm", note: "Apply anti-seize to prevent snapping." }, { part: "Intake Manifold Bolts", value: "9 Nm", note: "Sequential tightening is critical." }, { part: "48V BAS Mount Bolts", value: "25 Nm", note: "Crucial to torque perfectly for belt alignment." }, { part: "ZF 8HP Drain Plug", value: "12 Nm", note: "Fill strictly at 40°C temperature." } ],
