  engineeringData: { blockDesign: "Cast Aluminum 90-degree V6 block (EA839). Integrated directly with a 100kW permanent magnet synchronous electric motor sandwiched inside the transmission bellhousing.", crankshaft: "Forged Steel, massively reinforced to endure sudden, violent torque shocks from instantaneous electric motor engagement.", pistonSpeed: "18.5 m/s @ 6500 RPM. Features highly durable cast aluminum pistons with advanced low-friction skirt coatings.", alternator: "N/A (Uses the High Voltage traction motor acting as a heavy-duty generator during deceleration).", rotatingAssembly: { pistonConstruction: "Cast Aluminum, featuring a specialized asymmetrical crown optimized for direct injection.", wristPinDiameter: "22 mm.", connectingRodLength: "153 mm.", rodBoltSize: "M9 x 1.0 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.72." }, cylinderHead: { combustionChamberVol: "Pent-roof design with intake and exhaust ports reversed (intake outside, exhaust inside the V).", intakePortFlow: "24-valve DOHC. Highly susceptible to carbon buildup due to the complete lack of port fuel injection washing the valves.", valveSizes: "Intake: 34.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Audi Valvelift System (AVS) on the intake camshaft allowing B-Cycle operation for massive efficiency gains.", lifterType: "Hydraulic roller finger followers.", specialFeature: "The Hot-V design drastically minimizes the distance exhaust gases travel to the turbocharger, while the e-motor provides instant torque fill." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Electronically controlled variable displacement vane pump.", thermostatOpening: "Map-controlled electronic rotary valve thermostat.", oilCooler: "Water-to-oil heat exchanger located in the engine valley." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "250 Bar.", injectors: "6 Solenoid high-speed injectors." }, tuningLimits: { maxSafeTorqueStock: "800 Nm Total System Torque before the ZF 8HP hybrid separator clutches begin to slip.", maxSafePowerStock: "550 hp ICE.", maxSafeRPM: "7000 RPM ICE.", weakestLink: "HV Battery Degradation, OPF exhaust restriction, Fragile Electric A/C Compressor." }, electrical: { coils: "High-output COP.", ecu: "Bosch MG1 / High Voltage Hybrid Management System." } },
  recommendedParts: { description: "The PHEV Q8 demands fanatical preventative maintenance of the Hot-V cooling components and High Voltage peripherals to avoid catastrophic bills.", parts: [ { category: "Thermal Management Module", brand: "Genuine Audi", note: "Water pump assembly; highly prone to warping and leaking coolant." }, { category: "Timing Chain Kit", brand: "INA", note: "Includes updated, reinforced guides and improved hydraulic tensioners." }, { category: "Electric A/C Compressor", brand: "Denso", note: "Cools the HV Battery. Fails often and will completely disable the vehicle." }, { category: "Ignition Coils", brand: "Eldor", note: "Red RS3 coils provide vastly stronger spark to prevent OPF-melting misfires." }, { category: "Spark Plugs", brand: "NGK Laser Platinum", note: "Replace strictly every 60k km to prevent electrode degradation under boost." }, { category: "PCV Valve", brand: "Genuine Audi", note: "Saves the rear main crankshaft seal from a catastrophic blowout." }, { category: "Oil Filter", brand: "Mann-Filter", note: "High capacity synthetic media cartridge." }, { category: "Intake Manifold Gasket", brand: "Elring", note: "Required every 100k km for mandatory walnut blasting service." } ] },
