    fluidsAndDrivetrain: [ { interval: "80,000 km", timeLimit: "8 years", task: "ZF 8HP Hybrid ATF Service", details: "Drain and refill Lifeguard 8; replace integrated pan/filter unit.", parts: ["9.5L ATF", "Pan Filter"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "450 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Front Diff Oil", details: "Drain and refill 75W-90 GL-5.", parts: ["1.0L 75W-90"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Rear Diff Oil", details: "Drain and refill 75W-90 GL-5.", parts: ["1.2L 75W-90"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Transfer Case Flush", details: "Drain and refill G 055 515 A2 to prevent AWD binding.", parts: ["0.85L Fluid"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "110 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush entire system with DOT 4 Low Viscosity.", parts: ["1.2L DOT 4"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Haldex Calibration", details: "VCDS calibration for AWD clutch pack.", parts: ["Diagnostic"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ],
    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "Use VW 508 00 0W-20 strictly to protect the OPF filter from ash.", parts: ["7.6L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "160 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Critical to protect the Hot-V turbocharger from debris.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon filter replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "60,000 km", timeLimit: "4 years", task: "Fuel Filter", details: "Under chassis inline filter replacement.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "85 EUR" } ],
    ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Prevent misfires that can melt the OPF substrate.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement with upgraded Eldor units.", parts: ["6x Eldor Coils"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "300 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "PCV Valve", details: "Top engine oil separator replacement to prevent vacuum leaks.", parts: ["PCV Assembly"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Walnut Blasting", details: "Physically clean hardened carbon from the intake valves.", parts: ["Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "HV Battery Inspection", details: "VCDS State of Health (SOH) check for the lithium-ion pack.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Throttle Body Clean", details: "Remove carbon ring from the throttle flap.", parts: ["Cleaner"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "150,000 km", timeLimit: "N/A", task: "Wastegate Check", details: "Inspect turbo actuator arm for excessive play.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
