  engineeringData: { blockDesign: "Cast Compacted Graphite Iron (CGI) 90-degree V8 block (EA898). Exceptionally rigid and dense to withstand extreme twin-turbo diesel cylinder pressures without expanding.", crankshaft: "Forged Steel cross-plane design, supported by 5 oversized main bearings, engineered to endure the brutal 900Nm of continuous torque.", pistonSpeed: "15.0 m/s @ 4500 RPM.", alternator: "48V water-cooled Belt Alternator Starter (BAS), powering the EPC and active chassis roll bars.", rotatingAssembly: { pistonConstruction: "Cast Aluminum with internal oil cooling galleries and reinforced wrist pins.", wristPinDiameter: "32 mm.", connectingRodLength: "154 mm.", rodBoltSize: "M10 x 1.0 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "60.0 mm.", rodRatio: "1.69." }, cylinderHead: { combustionChamberVol: "Flat head design, combustion occurs within the piston bowl.", intakePortFlow: "32-valve DOHC with dual intake ports per cylinder (swirl and fill port).", valveSizes: "Intake: 29.5 mm / Exhaust: 27.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Audi Valvelift System (AVS) on the exhaust side to direct exhaust flow efficiently between the two turbos.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "The sequential turbo system uses AVS to feed only one turbo at low RPMs, while the EPC provides instant boost until exhaust gases take over." }, oilAndCooling: { oilSquirters: "Yes, dual under-piston cooling jets per cylinder.", oilPumpType: "Chain-driven fully variable gear pump.", thermostatOpening: "87°C Mechanical.", oilCooler: "Massive water-to-oil heat exchanger situated directly in the engine 'V'." }, fuelSystem: { systemType: "Bosch MD1 Common Rail.", maxPressure: "2500 Bar.", injectors: "8 extremely fast Bosch piezo injectors backed by dual CP4.2 pumps." }, tuningLimits: { maxSafeTorqueStock: "1100 Nm, matching the ZF 8HP90 transmission limits.", maxSafePowerStock: "550 hp.", maxSafeRPM: "5000 RPM.", weakestLink: "Twin CP4.2 Pumps, 48V EPC Electronics, DPF flow restriction." }, electrical: { coils: "N/A (Compression ignition).", ecu: "Dual Bosch MD1 Master/Slave." } },
  recommendedParts: { description: "The V8 TDI demands fanatical maintenance; oil leaks and complex chains require proactive care.", parts: [ { category: "Twin Disaster Prevention Kits", brand: "Whitbread / Aftermarket", note: "CRITICAL: Install immediately to save 8 injectors if either CP4 pump fails." }, { category: "Upper Chain Tensioners", brand: "INA", note: "Replace instantly if cold-start rattling occurs." }, { category: "Oil Cooler Reseal Kit", brand: "Elring", note: "Fixes massive oil pooling in the engine V." }, { category: "48V EPC Unit", brand: "Valeo / Audi", note: "Expensive electric compressor, inspect for bearing noise." }, { category: "Glow Plugs", brand: "Beru / Bosch", note: "Requires 8x units. Vital for DPF regen." }, { category: "AdBlue Heater Element", brand: "Bosch", note: "Fails frequently, locking the ECU." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "Replace STRICTLY every 20k km." }, { category: "Oil Filter", brand: "Mann-Filter", note: "Use strictly with VW 507 00 oils." } ] },
