  engineeringData: { blockDesign: "Cast Aluminum 90-degree V8 block (EA825). Features a Hot-V layout where the exhaust manifolds and twin turbochargers are inside the V, drastically improving thermal efficiency and turbo spool time.", crankshaft: "Forged Steel, massively reinforced, and supported by 5 oversized main bearings to ensure absolute rigidity under extreme low-end torque loads.", pistonSpeed: "19.0 m/s @ 6800 RPM. Features highly durable cast aluminum pistons with advanced low-friction coatings.", alternator: "48V water-cooled Belt Alternator Starter (BAS), enabling prolonged engine-off coasting and providing instant torque fill.", rotatingAssembly: { pistonConstruction: "Cast Aluminum, featuring a specialized asymmetrical crown.", wristPinDiameter: "22 mm.", connectingRodLength: "153 mm.", rodBoltSize: "M9 x 1.0 stretch bolts.", crankMainJournal: "65.0 mm.", crankRodJournal: "56.0 mm.", rodRatio: "1.72." }, cylinderHead: { combustionChamberVol: "Pent-roof design with intake and exhaust ports reversed (intake outside, exhaust inside the V).", intakePortFlow: "32-valve DOHC. Highly susceptible to carbon buildup due to pure FSI design.", valveSizes: "Intake: 34.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Audi Valvelift System (AVS) enabling Cylinder on Demand (COD) deactivation for highway efficiency.", lifterType: "Hydraulic roller finger followers.", specialFeature: "The Hot-V design minimizes the distance exhaust gases travel to the twin-scroll turbos, eradicating turbo lag." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Electronically controlled variable displacement vane pump.", thermostatOpening: "Map-controlled electronic rotary valve thermostat.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "FSI High Pressure Direct Injection.", maxPressure: "250 Bar.", injectors: "8 Solenoid high-speed injectors." }, tuningLimits: { maxSafeTorqueStock: "1050 Nm, matching the ZF 8HP95 transmission limits.", maxSafePowerStock: "850 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "48V BAS System, OPF restriction, Turbo Oil Strainer Screen." }, electrical: { coils: "High-output COP.", ecu: "Bosch MG1." } },
